/**
 * chatMessenger + chatWhatsapp — themed conversation scenes.
 *
 * ConversationThread owns bubble chrome, typing, receipts, chips, timing,
 * orientation, and export-safe emoji rendering. This template translates the
 * editable msg1..msg5 fields into the primitive's message collection.
 */

import * as React from "react";
import type { VariableField } from "../video-config";
import type { SceneTemplateProps } from "./types";
import { normalizeTextVar } from "./normalize-var";
import { ConversationThread } from "../primitives/social/ConversationThread";

export const socialConversationSchema: Record<string, VariableField> = {
  msg1: {
    type: "string",
    label: "Message 1 (received)",
    default: "Have you tried it yet?",
    required: true,
    description: "First message — left/received by default. Append |in or |out to override side. Aim for 3-4 messages total; use 5 with date chips only for a real time gap in a 10s+ scene.",
  },
  msg2: {
    type: "string",
    label: "Message 2 (received or sent)",
    default: "It saves me hours every week",
    required: true,
    description: "Second message — left/received by default. Override with |out for ping-pong.",
  },
  msg3: {
    type: "string",
    label: "Message 3 (received)",
    default: "And the team loves it",
    required: true,
    description: "Third message — left/received by default. Leave blank for a two-message exchange.",
  },
  msg4: {
    type: "string",
    label: "Message 4 (sent)",
    default: "Sounds great — sharing access now",
    description: "Fourth message — right/sent by default. Optional; most chats end here.",
  },
  dateChip1: {
    type: "string",
    label: "Date chip 1",
    default: "",
    description: "Optional date label before message 4. Use only for a real time gap.",
  },
  dateChip2: {
    type: "string",
    label: "Date chip 2",
    default: "",
    description: "Optional date label before message 5. Use only for a real time gap.",
  },
  msg5: {
    type: "string",
    label: "Message 5 (sent)",
    default: "",
    description: "Optional fifth message — right/sent by default.",
  },
};

const sharedMessages = {
  msg1: "Have you tried it yet?",
  msg2: "It saves me hours every week",
  msg3: "And the team loves it",
  msg4: "Sounds great — sharing access now",
  msg5: "",
  dateChip1: "",
  dateChip2: "",
};

export const socialMessengerDefaults: Record<string, unknown> = {
  theme: "messenger",
  ...sharedMessages,
};

export const socialWhatsappDefaults: Record<string, unknown> = {
  theme: "whatsapp",
  ...sharedMessages,
};

const DEFAULT_SIDES: Record<number, "left" | "right"> = {
  1: "left",
  2: "left",
  3: "left",
  4: "right",
  5: "right",
};

function buildMessages(variables: Record<string, unknown>) {
  const messages: Array<{ author: string; text: string; side: "left" | "right" }> = [];
  for (let index = 1; index <= 5; index += 1) {
    let text = normalizeTextVar(variables[`msg${index}`]).trim();
    if (!text) continue;
    let side = DEFAULT_SIDES[index] ?? (index % 2 === 1 ? "left" : "right");
    if (text.endsWith("|in")) {
      side = "left";
      text = text.slice(0, -3).trim();
    } else if (text.endsWith("|out")) {
      side = "right";
      text = text.slice(0, -4).trim();
    }
    messages.push({ author: side === "left" ? "Customer" : "You", text, side });
  }
  return messages;
}

export const SocialConversationTemplate: React.FC<SceneTemplateProps> = ({
  variables,
  progress,
  beatIntensity,
  width,
  height,
  sceneDuration,
  safeZone,
}) => {
  const theme = String(variables.theme || "messenger").toLowerCase() === "whatsapp"
    ? "whatsapp"
    : "messenger";

  return (
    <div style={{ width, height, position: "relative", overflow: "hidden", backgroundColor: theme === "whatsapp" ? "#EFE7DC" : "#ffffff" }}>
      {/* [slot: hero] ConversationThread includes the theme-specific canvas. */}
      <ConversationThread
        progress={progress}
        width={width}
        height={height}
        sceneDuration={sceneDuration ?? 8}
        messages={buildMessages(variables)}
        theme={theme}
        dateChip1={String(variables.dateChip1 || "")}
        dateChip2={String(variables.dateChip2 || "")}
        safeZoneTop={Math.max(safeZone.top, height * 0.08)}
        beatIntensity={beatIntensity}
      />
    </div>
  );
};

/**
 * ConversationThread — multi-bubble chat thread with staggered reveal,
 * typing indicators, and (for WhatsApp) animated read receipts.
 *
 * Lifted from `social-conversation.tsx`. The primitive owns:
 *   - the centered chat column (full-width portrait / ~72% landscape)
 *   - per-message typing → bubble pop sequence
 *   - WhatsApp tick state progression (clock → sent → delivered → read)
 *   - optional date chips inserted between specific messages
 *   - the WhatsApp compose bar (decorative — drawn 1:1 from the source)
 *
 * It does NOT own a SceneBackground gradient/media or a headline overlay.
 * The primitive fills its own backdrop with the theme background color so
 * the bubbles always have correct contrast; if a caller wants the scene
 * gradient to show through, drop this primitive on top of a SceneBackground.
 *
 * The source template parses messages from `msg1..msg5` variables plus a
 * `|in`/`|out` suffix override. This primitive accepts the already-parsed
 * `messages` array so callers can pre-split however they like.
 *
 * Local helpers (`easeOutBack`, `tickStateAt`, `timingForCount`) are
 * inlined because the source defined them locally; they are not exported.
 *
 * Props:
 *  - progress      — scene progress 0..1
 *  - width / height — frame dimensions
 *  - sceneDuration — seconds; drives the 1.5 Hz typing-dot ripple in real time
 *  - messages      — array of `{ author, text, side }`. `author` is
 *                    decorative (not rendered in either theme today) but
 *                    accepted so callers don't lose data when round-tripping.
 *  - theme         — "whatsapp" or "messenger" (iMessage). Default "whatsapp".
 *  - safeZoneTop   — top inset to clear the social overlay UI. Default 8% of height.
 *  - accent        — brand accent (kept for parity; today's chrome is locked
 *                    to WhatsApp/iMessage native palettes for realism)
 *  - beatIntensity — accepted for parity; not currently applied
 */

import * as React from "react";
import { interpolate } from "../../motion";
import { stripPipe } from "../../typography";
import { renderWithEmoji } from "../../emoji/emoji-text";

const CLAMP = {
  extrapolateLeft: "clamp" as const,
  extrapolateRight: "clamp" as const,
};

/* Reference timeline length — every reveal time is a fraction of this. */
const REF_DURATION = 16;

/* easeOutBack — same overshoot curve the source uses for pop-ins. */
function easeOutBack(t: number): number {
  const c1 = 1.70158;
  const c3 = c1 + 1;
  return 1 + c3 * Math.pow(t - 1, 3) + c1 * Math.pow(t - 1, 2);
}

/* WhatsApp palette */
const WA = {
  bg: "#EFE7DC",
  incomingBubble: "#FFFFFF",
  outgoingBubble: "#D9F4C7",
  text: "#0E0E0E",
  textMuted: "#6E6E73",
  accent: "#0A8F76",
  chipBg: "#F1E9D8",
  chipText: "#3C342A",
  navBg: "#F1E9DA",
  inputBg: "#FFFFFF",
  inputBorder: "rgba(0,0,0,0.06)",
  outgoingTime: "#5C6B4E",
};

/* iMessage palette */
const IM = {
  bg: "#ffffff",
  bubbleOut: "#007AFF",
  bubbleIn: "#E9E9EB",
  textOut: "#ffffff",
  textIn: "#000000",
  dotsColor: "#8E8E93",
};

interface InternalMessage {
  side: "left" | "right";
  text: string;
  author: string;
  typingStart: number;
  bubbleStart: number;
  time: string;
}

/* WhatsApp reference timing — mirrors source 5-message cadence. */
const WA_TIMING_5: Array<{ typingStart: number; bubbleStart: number; time: string }> = [
  { typingStart: 0.6, bubbleStart: 1.4, time: "21:54" },
  { typingStart: 2.2, bubbleStart: 3.0, time: "21:55" },
  { typingStart: 3.8, bubbleStart: 4.8, time: "21:56" },
  { typingStart: 6.2, bubbleStart: 7.2, time: "12:35" },
  { typingStart: 10.0, bubbleStart: 11.0, time: "11:17" },
];

function timingForCount(count: number): Array<{ typingStart: number; bubbleStart: number; time: string }> {
  if (count >= 5) return WA_TIMING_5.slice(0, count);
  const slot = 12 / count;
  const out: Array<{ typingStart: number; bubbleStart: number; time: string }> = [];
  for (let i = 0; i < count; i++) {
    const start = 0.6 + i * slot;
    out.push({
      typingStart: start,
      bubbleStart: start + slot * 0.5,
      time: WA_TIMING_5[Math.min(i, 4)].time,
    });
  }
  return out;
}

/* Read-receipt phases (WhatsApp). */
type TickState = "clock" | "sent" | "delivered" | "read";

function tickStateAt(refTimeSinceSent: number): TickState {
  if (refTimeSinceSent < 0.5) return "clock";
  if (refTimeSinceSent < 1.1) return "sent";
  if (refTimeSinceSent < 1.8) return "delivered";
  return "read";
}

const ClockIcon: React.FC<{ s: number }> = ({ s }) => (
  <svg width={12 * s} height={12 * s} viewBox="0 0 12 12" style={{ marginLeft: 4 * s }}>
    <circle cx="6" cy="6" r="5" fill="none" stroke="#8C8C92" strokeWidth="1.2" />
    <path d="M6 3 v3.5 l2 1" stroke="#8C8C92" strokeWidth="1.2" fill="none" strokeLinecap="round" />
  </svg>
);

const Ticks: React.FC<{ state: TickState; s: number }> = ({ state, s }) => {
  if (state === "clock") return <ClockIcon s={s} />;
  const color = state === "read" ? "#53BDEB" : "#8C8C92";
  return (
    <svg width={16 * s} height={11 * s} viewBox="0 0 16 11" style={{ marginLeft: 4 * s }}>
      <path
        d="M1 6 l3 3 l6 -7"
        stroke={color}
        strokeWidth={1.3}
        fill="none"
        strokeLinecap="round"
        strokeLinejoin="round"
        opacity={state === "sent" ? 0 : 1}
      />
      <path
        d="M5 6 l3 3 l7 -8"
        stroke={color}
        strokeWidth={1.3}
        fill="none"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
};

const ComposeBar: React.FC<{ s: number }> = ({ s }) => {
  const stroke = "#1A1A1A";
  return (
    <div
      style={{
        background: WA.navBg,
        borderTop: "1px solid rgba(0,0,0,0.05)",
        padding: `${10 * s}px ${14 * s}px ${12 * s}px`,
        display: "flex",
        alignItems: "center",
        gap: 14 * s,
      }}
    >
      <svg width={30 * s} height={30 * s} viewBox="0 0 30 30" style={{ flexShrink: 0 }}>
        <path d="M15 5 v20 M5 15 h20" stroke={stroke} strokeWidth="1.8" strokeLinecap="round" />
      </svg>
      <div
        style={{
          flex: 1,
          height: 40 * s,
          background: WA.inputBg,
          borderRadius: 22 * s,
          position: "relative",
          border: `0.5px solid ${WA.inputBorder}`,
        }}
      >
        <div
          style={{
            position: "absolute",
            right: 12 * s,
            top: "50%",
            transform: "translateY(-50%)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          <svg width={28 * s} height={28 * s} viewBox="0 0 24 24" fill="none" style={{ display: "block" }}>
            <path
              d="M3 5 a2 2 0 0 1 2 -2 h10 a2 2 0 0 1 2 2 v6 l-6 6 h-6 a2 2 0 0 1 -2 -2 z M17 11 a4 4 0 0 0 -4 4 v2"
              stroke="#555"
              strokeWidth="1.5"
              fill="none"
              strokeLinejoin="round"
              strokeLinecap="round"
            />
          </svg>
        </div>
      </div>
      <svg width={28 * s} height={24 * s} viewBox="0 0 28 24" fill="none" style={{ flexShrink: 0 }}>
        <path
          d="M3 6 h5 l2 -3 h8 l2 3 h5 a1 1 0 0 1 1 1 v14 a1 1 0 0 1 -1 1 h-22 a1 1 0 0 1 -1 -1 v-14 a1 1 0 0 1 1 -1 z"
          stroke={stroke}
          strokeWidth="1.6"
          fill="none"
          strokeLinejoin="round"
        />
        <circle cx="14" cy="14" r="4.5" stroke={stroke} strokeWidth="1.6" fill="none" />
      </svg>
      <svg width={20 * s} height={26 * s} viewBox="0 0 20 26" fill="none" style={{ flexShrink: 0 }}>
        <rect x="7" y="2" width="6" height="13" rx="3" stroke={stroke} strokeWidth="1.6" fill="none" />
        <path
          d="M3 12 a7 7 0 0 0 14 0 M10 19 v4 M7 23 h6"
          stroke={stroke}
          strokeWidth="1.6"
          fill="none"
          strokeLinecap="round"
        />
      </svg>
    </div>
  );
};

const TypingBubble: React.FC<{
  side: "left" | "right";
  pop: number;
  realTimeSeconds: number;
  s: number;
  theme: "whatsapp" | "messenger";
}> = ({ side, pop, realTimeSeconds, s, theme }) => {
  if (pop <= 0) return null;
  const isOut = side === "right";
  const isWA = theme === "whatsapp";
  const dotColor = isWA ? (isOut ? "#6B8A55" : "#8C8C92") : IM.dotsColor;
  const bg = isWA
    ? isOut
      ? WA.outgoingBubble
      : WA.incomingBubble
    : isOut
      ? IM.bubbleOut
      : IM.bubbleIn;

  return (
    <div
      style={{
        display: "flex",
        justifyContent: isOut ? "flex-end" : "flex-start",
        padding: `${2 * s}px ${(isWA ? 10 : 14) * s}px`,
        opacity: pop,
        transform: `scale(${0.9 + 0.1 * pop})`,
        transformOrigin: isOut ? "right bottom" : "left bottom",
      }}
    >
      <div
        style={{
          background: bg,
          borderRadius: (isWA ? 14 : 18) * s,
          ...(isWA
            ? {
                borderTopLeftRadius: isOut ? 14 * s : 2 * s,
                borderTopRightRadius: isOut ? 2 * s : 14 * s,
              }
            : {}),
          padding: `${(isWA ? 10 : 12) * s}px ${(isWA ? 12 : 16) * s}px`,
          display: "flex",
          gap: 5 * s,
          alignItems: "center",
          ...(isWA
            ? { boxShadow: `0 ${1 * s}px ${1 * s}px rgba(0,0,0,0.06)` }
            : {}),
        }}
      >
        {[0, 1, 2].map((i) => {
          const phase = (realTimeSeconds * 1.6 + i * 0.2) % 1;
          const y = Math.sin(phase * Math.PI * 2) * 2.5 * s;
          const op = 0.45 + 0.55 * Math.max(0, Math.sin(phase * Math.PI));
          const dotSize = isWA ? 6 * s : 7 * s;
          return (
            <div
              key={i}
              style={{
                width: dotSize,
                height: dotSize,
                borderRadius: dotSize / 2,
                background: dotColor,
                transform: `translateY(${-y}px)`,
                opacity: op,
              }}
            />
          );
        })}
      </div>
    </div>
  );
};

const DateChip: React.FC<{ label: string; chipProgress: number; s: number }> = ({
  label,
  chipProgress,
  s,
}) => {
  if (chipProgress <= 0) return null;
  return (
    <div
      style={{
        display: "flex",
        justifyContent: "center",
        margin: `${12 * s}px 0 ${8 * s}px`,
        opacity: chipProgress,
        transform: `scale(${0.88 + 0.12 * chipProgress})`,
      }}
    >
      <div
        style={{
          background: WA.chipBg,
          color: WA.chipText,
          padding: `${7 * s}px ${16 * s}px`,
          borderRadius: 9 * s,
          fontSize: 17 * s,
          fontWeight: 600,
          boxShadow: `0 ${1 * s}px ${1.5 * s}px rgba(0,0,0,0.05)`,
        }}
      >
        {label}
      </div>
    </div>
  );
};

const IncomingBubble: React.FC<{
  children: React.ReactNode;
  time: string;
  pop: number;
  s: number;
}> = ({ children, time, pop, s }) => (
  <div
    style={{
      display: "flex",
      justifyContent: "flex-start",
      padding: `${2 * s}px ${10 * s}px`,
      opacity: pop,
      transform: `translateY(${(1 - pop) * 6 * s}px) scale(${0.97 + 0.03 * pop})`,
      transformOrigin: "left bottom",
    }}
  >
    <div
      style={{
        maxWidth: "82%",
        background: WA.incomingBubble,
        borderRadius: 10 * s,
        borderTopLeftRadius: 2 * s,
        padding: `${12 * s}px ${16 * s}px ${11 * s}px`,
        fontSize: 23 * s,
        lineHeight: `${29 * s}px`,
        color: WA.text,
        boxShadow: `0 ${1 * s}px ${1 * s}px rgba(0,0,0,0.06)`,
        position: "relative",
      }}
    >
      <div style={{ paddingRight: 64 * s }}>{children}</div>
      <div
        style={{
          position: "absolute",
          right: 14 * s,
          bottom: 8 * s,
          fontSize: 15 * s,
          color: WA.textMuted,
        }}
      >
        {time}
      </div>
    </div>
  </div>
);

const OutgoingBubble: React.FC<{
  children: React.ReactNode;
  time: string;
  tickState: TickState;
  pop: number;
  s: number;
}> = ({ children, time, tickState, pop, s }) => (
  <div
    style={{
      display: "flex",
      justifyContent: "flex-end",
      padding: `${2 * s}px ${10 * s}px`,
      opacity: pop,
      transform: `translateY(${(1 - pop) * 8 * s}px) scale(${0.96 + 0.04 * pop})`,
      transformOrigin: "right bottom",
    }}
  >
    <div
      style={{
        maxWidth: "82%",
        background: WA.outgoingBubble,
        borderRadius: 10 * s,
        borderTopRightRadius: 2 * s,
        padding: `${12 * s}px ${16 * s}px ${11 * s}px`,
        fontSize: 23 * s,
        lineHeight: `${29 * s}px`,
        color: WA.text,
        boxShadow: `0 ${1 * s}px ${1 * s}px rgba(0,0,0,0.06)`,
        position: "relative",
      }}
    >
      <div style={{ paddingRight: 88 * s }}>{children}</div>
      <div
        style={{
          position: "absolute",
          right: 14 * s,
          bottom: 8 * s,
          fontSize: 15 * s,
          color: WA.outgoingTime,
          display: "flex",
          alignItems: "center",
        }}
      >
        {time}
        <Ticks state={tickState} s={s} />
      </div>
    </div>
  </div>
);

const CHIP_TIMING = {
  monday: { start: 5.8, end: 6.2 },
  yesterday: { start: 9.6, end: 10.0 },
};

export interface ConversationThreadProps {
  progress: number;
  width: number;
  height: number;
  sceneDuration: number;
  messages: Array<{ author: string; text: string; side: "left" | "right" }>;
  theme?: "whatsapp" | "messenger";
  /** Optional date chips inserted before specific message indices.
   *  Default behavior matches the source: chip1 before message 4 (index 3),
   *  chip2 before message 5 (index 4). Leave blank to suppress. */
  dateChip1?: string;
  dateChip2?: string;
  safeZoneTop?: number;
  accent?: string;
  beatIntensity?: number;
}

export const ConversationThread: React.FC<ConversationThreadProps> = ({
  progress,
  width,
  height,
  sceneDuration,
  messages: rawMessages,
  theme = "whatsapp",
  dateChip1 = "",
  dateChip2 = "",
  safeZoneTop,
}) => {
  const isLandscape = width > height;
  const colWidth = isLandscape ? width * 0.72 : width;
  const colLeft = (width - colWidth) / 2;
  const s = Math.min(width, height) / 534;
  const isWhatsApp = theme === "whatsapp";

  // Apply stripPipe + attach timing
  const sanitized = rawMessages
    .map((m) => ({ ...m, text: stripPipe(m.text || "").trim() }))
    .filter((m) => m.text.length > 0);
  const timing = timingForCount(Math.max(1, sanitized.length));
  const messages: InternalMessage[] = sanitized.map((m, i) => ({
    side: m.side,
    text: m.text,
    author: m.author,
    typingStart: timing[i].typingStart,
    bubbleStart: timing[i].bubbleStart,
    time: timing[i].time,
  }));

  const realTimeSeconds = progress * sceneDuration;
  const refT = progress * REF_DURATION;
  const topPad = safeZoneTop != null ? safeZoneTop : height * 0.08;

  const chip1Label = stripPipe(dateChip1 || "").trim();
  const chip2Label = stripPipe(dateChip2 || "").trim();

  const popIn = (t: number, start: number, dur = 0.4): number => {
    if (t <= start) return 0;
    if (t >= start + dur) return 1;
    return easeOutBack((t - start) / dur);
  };

  const ramp = (t: number, start: number, end: number): number => {
    if (t <= start) return 0;
    if (t >= end) return 1;
    return (t - start) / (end - start);
  };

  if (isWhatsApp) {
    return (
      <div
        style={{
          position: "absolute",
          inset: 0,
          background: WA.bg,
          overflow: "hidden",
          fontFamily: '-apple-system, "SF Pro Text", system-ui',
        }}
      >
        <div
          style={{
            position: "absolute",
            left: colLeft,
            width: colWidth,
            top: 0,
            height,
            display: "flex",
            flexDirection: "column",
          }}
        >
          <div style={{ flex: 1, position: "relative", overflow: "hidden" }}>
            <div
              style={{
                position: "absolute",
                left: 0,
                right: 0,
                top: 0,
                display: "flex",
                flexDirection: "column",
                gap: 2 * s,
                padding: `${topPad}px 0 ${10 * s}px`,
              }}
            >
              {messages.map((msg, i) => {
                const typingPop = popIn(refT, msg.typingStart, 0.25);
                const typingFade = interpolate(
                  refT,
                  [msg.bubbleStart - 0.1, msg.bubbleStart],
                  [1, 0],
                  CLAMP,
                );
                const showTyping = refT >= msg.typingStart && refT < msg.bubbleStart;
                const bubblePop = popIn(refT, msg.bubbleStart, 0.4);
                const showBubble = refT >= msg.bubbleStart;
                const isOut = msg.side === "right";

                const refSinceSent = refT - msg.bubbleStart - 0.4;
                const tickState = isOut ? tickStateAt(Math.max(0, refSinceSent)) : "read";

                const chipBeforeThis: { label: string; progress: number } | null = (() => {
                  if (i === 3 && chip1Label) {
                    return {
                      label: chip1Label,
                      progress: ramp(refT, CHIP_TIMING.monday.start, CHIP_TIMING.monday.end),
                    };
                  }
                  if (i === 4 && chip2Label) {
                    return {
                      label: chip2Label,
                      progress: ramp(refT, CHIP_TIMING.yesterday.start, CHIP_TIMING.yesterday.end),
                    };
                  }
                  return null;
                })();

                return (
                  <React.Fragment key={i}>
                    {chipBeforeThis && (
                      <DateChip
                        label={chipBeforeThis.label}
                        chipProgress={chipBeforeThis.progress}
                        s={s}
                      />
                    )}

                    {showTyping && (
                      <div style={{ opacity: typingPop * typingFade }}>
                        <TypingBubble
                          side={msg.side}
                          pop={typingPop}
                          realTimeSeconds={realTimeSeconds}
                          s={s}
                          theme="whatsapp"
                        />
                      </div>
                    )}

                    {showBubble &&
                      (isOut ? (
                        <OutgoingBubble pop={bubblePop} time={msg.time} tickState={tickState} s={s}>
                          {renderWithEmoji(msg.text, 23 * s)}
                        </OutgoingBubble>
                      ) : (
                        <IncomingBubble pop={bubblePop} time={msg.time} s={s}>
                          {renderWithEmoji(msg.text, 23 * s)}
                        </IncomingBubble>
                      ))}
                  </React.Fragment>
                );
              })}

              <div style={{ height: 12 * s }} />
            </div>
          </div>

          <ComposeBar s={s} />
        </div>
      </div>
    );
  }

  // iMessage render
  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        background: IM.bg,
        overflow: "hidden",
        fontFamily: "-apple-system, 'SF Pro', 'Helvetica Neue', Helvetica, Arial, sans-serif",
      }}
    >
      <div
        style={{
          position: "absolute",
          left: colLeft,
          width: colWidth,
          top: 0,
          height,
          padding: `${topPad}px 0 ${20 * s}px`,
          display: "flex",
          flexDirection: "column",
          gap: 4 * s,
        }}
      >
        {messages.map((msg, i) => {
          const typingPop = popIn(refT, msg.typingStart, 0.25);
          const typingFade = interpolate(
            refT,
            [msg.bubbleStart - 0.1, msg.bubbleStart],
            [1, 0],
            CLAMP,
          );
          const showTyping = refT >= msg.typingStart && refT < msg.bubbleStart;
          const bubblePop = popIn(refT, msg.bubbleStart, 0.4);
          const showBubble = refT >= msg.bubbleStart;
          const isOut = msg.side === "right";

          return (
            <React.Fragment key={i}>
              {showTyping && (
                <div style={{ opacity: typingPop * typingFade }}>
                  <TypingBubble
                    side={msg.side}
                    pop={typingPop}
                    realTimeSeconds={realTimeSeconds}
                    s={s}
                    theme="messenger"
                  />
                </div>
              )}

              {showBubble && (
                <div
                  style={{
                    display: "flex",
                    justifyContent: isOut ? "flex-end" : "flex-start",
                    padding: `${2 * s}px ${14 * s}px`,
                    opacity: bubblePop,
                    transform: `translateY(${(1 - bubblePop) * 8 * s}px) scale(${0.96 + 0.04 * bubblePop})`,
                    transformOrigin: isOut ? "right bottom" : "left bottom",
                  }}
                >
                  <div
                    style={{
                      maxWidth: "75%",
                      background: isOut ? IM.bubbleOut : IM.bubbleIn,
                      color: isOut ? IM.textOut : IM.textIn,
                      borderRadius: 22 * s,
                      padding: `${12 * s}px ${18 * s}px`,
                      fontSize: 23 * s,
                      lineHeight: `${29 * s}px`,
                    }}
                  >
                    {renderWithEmoji(msg.text, 23 * s)}
                  </div>
                </div>
              )}
            </React.Fragment>
          );
        })}
      </div>
    </div>
  );
};

/**
 * EmojiText / renderWithEmoji — split a string into text runs + color-emoji
 * runs, rendering each color emoji as an inline emoji-PNG <img> (via <Emoji>)
 * while leaving everything else as plain text.
 *
 * Why this exists: raw-unicode emoji fall through to the OS emoji font (Mac =
 * Apple, Linux = Noto), so the three render paths (preview / client SVG export
 * / server Puppeteer) disagree. Wrapping every template/AI-supplied string here
 * makes ALL color emoji render as the same mapped PNG in all three.
 *
 * What it does NOT touch: monochrome symbols (★ ✦ ✓ → ↑ …). Those render
 * identically as text across OSes, and imaging them would be wrong. The gate
 * is `emojiToDataUri()` — only clusters that resolve to a PNG in the
 * map become <img>; anything else (monochrome symbols, unmapped/custom
 * emoji, skin-tone variants not in the set) stays raw text.
 *
 * Segmentation: grapheme clusters via Intl.Segmenter so ZWJ sequences
 * (👩‍💻) and skin-tone modifiers (👍🏽) stay single units. Adjacent emoji
 * clusters each render as their own <img> in sequence.
 *
 * Sizing: each emoji <img> is sized to `fontSizePx` (the surrounding font
 * size) so the emoji box matches a glyph box — width/line-count stay
 * ~identical to the raw-text layout, which keeps fitTextSize / archetype
 * char-count measurement valid (all string-based, never DOM-measured).
 */

import * as React from "react";
import { Emoji, emojiToDataUri } from "./index";

// Coarse "is this cluster a color-emoji candidate?" test. Deliberately broad:
// the real decision is whether emojiToDataUri() resolves it to a mapped PNG.
// This regex only needs to (a) catch the OS-divergent color ranges and (b)
// avoid flagging plain text/whitespace so we don't merge text into emoji runs.
//
//  - \u{1F000}-\u{1FAFF}  — main emoji planes (most pictographs)
//  - \u{2600}-\u{27BF}    — misc symbols + dingbats (color when + FE0F)
//  - \u{2B00}-\u{2BFF}    — stars/arrows block (⭐ lives here)
//  - \u{1F1E6}-\u{1F1FF}  — regional indicators (flags)
//  - \u{1F3FB}-\u{1F3FF}  — skin-tone modifiers
//  - \u{FE0F} | \u{200D} | \u{20E3} — VS16 / ZWJ / keycap combiners
//
// Combining/joiner codepoints (FE0F, ZWJ, keycap) are matched via alternation
// rather than inside the character class — eslint's
// no-misleading-character-class flags combining chars inside `[...]`, and
// alternation is equivalent here (we only test, never capture).
const EMOJI_CANDIDATE =
  /[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{2B00}-\u{2BFF}\u{1F1E6}-\u{1F1FF}]|[\u{1F3FB}-\u{1F3FF}]|\u{FE0F}|\u{200D}|\u{20E3}/u;

function isEmojiCandidate(cluster: string): boolean {
  return EMOJI_CANDIDATE.test(cluster);
}

/** Split text into grapheme clusters (ZWJ + skin-tone safe). */
function toGraphemes(text: string): string[] {
  const Seg = (Intl as unknown as { Segmenter?: typeof Intl.Segmenter }).Segmenter;
  if (Seg) {
    const seg = new Seg(undefined, { granularity: "grapheme" });
    const out: string[] = [];
    for (const { segment } of seg.segment(text)) out.push(segment);
    return out;
  }
  // Fallback: code-point spread. Won't keep ZWJ/skin-tone as single units, so
  // those land as separate clusters; emojiToDataUri's FE0F tolerance + the raw
  // fallback keep them from breaking. Modern browsers all have Segmenter.
  return Array.from(text);
}

export interface RenderWithEmojiOptions {
  /** vertical-align passed to each <Emoji>. */
  verticalAlign?: React.CSSProperties["verticalAlign"];
  /** Extra style merged onto each emoji <img>. */
  emojiStyle?: React.CSSProperties;
}

/**
 * Split `text` into an array of React nodes — plain-text strings interleaved
 * with <Emoji> images for every mapped color emoji. Returns a single-element
 * `[text]` fast-path when there are no color emoji (the common case), so
 * non-emoji text pays ~one regex test.
 *
 * @param text         the string to render
 * @param fontSizePx   surrounding font size in px (emoji box = this size)
 */
export function renderWithEmoji(
  text: string,
  fontSizePx: number,
  opts?: RenderWithEmojiOptions,
): React.ReactNode[] {
  if (!text) return [text];
  // Cheap bail-out: if the whole string has no emoji-range codepoint, return
  // it untouched (no segmentation, no array churn) — the hot path for the vast
  // majority of titles/bodies.
  if (!EMOJI_CANDIDATE.test(text)) return [text];

  const clusters = toGraphemes(text);
  const nodes: React.ReactNode[] = [];
  let textBuf = "";
  let key = 0;

  const flushText = () => {
    if (textBuf) {
      nodes.push(textBuf);
      textBuf = "";
    }
  };

  for (const cluster of clusters) {
    const uri = isEmojiCandidate(cluster) ? emojiToDataUri(cluster) : null;
    if (uri) {
      flushText();
      nodes.push(
        <Emoji
          key={`e${key++}`}
          char={cluster}
          size={fontSizePx}
          verticalAlign={opts?.verticalAlign}
          style={opts?.emojiStyle}
        />,
      );
    } else {
      textBuf += cluster;
    }
  }
  flushText();
  return nodes;
}

/**
 * Per-code-unit emoji plan for the typewriter archetype, which reveals text
 * one UTF-16 code unit at a time and indexes by `text.length`. We can't just
 * call renderWithEmoji there (it would re-segment and desync the visibleChars
 * counter), so this maps each cluster's START code-unit index to its emoji-PNG
 * data URI and marks the cluster's CONTINUATION indices as covered (render
 * nothing for them — the start index's <img> already spans the whole cluster).
 *
 * Returns null when the text contains no mapped color emoji (the common case),
 * so the typewriter render keeps its plain per-char path.
 */
export interface EmojiTypewriterPlan {
  /** code-unit index → full emoji cluster char (cluster start). */
  starts: Map<number, string>;
  /** code-unit indices that are continuations of a cluster (render nothing). */
  covered: Set<number>;
}

export function planTypewriterEmoji(text: string): EmojiTypewriterPlan | null {
  if (!text || !EMOJI_CANDIDATE.test(text)) return null;
  const starts = new Map<number, string>();
  const covered = new Set<number>();
  let idx = 0;
  let found = false;
  for (const cluster of toGraphemes(text)) {
    const len = cluster.length; // UTF-16 code units
    if (isEmojiCandidate(cluster) && emojiToDataUri(cluster)) {
      found = true;
      // Store the WHOLE cluster char (not just the start unit) so callers can
      // pass it straight to <Emoji> for a correct map lookup.
      starts.set(idx, cluster);
      for (let k = 1; k < len; k++) covered.add(idx + k);
    }
    idx += len;
  }
  return found ? { starts, covered } : null;
}

export interface EmojiTextProps {
  /** The text to render, color emoji replaced with emoji-PNG <img>. */
  children: string;
  /** Surrounding font size in px — sizes each emoji image to match a glyph. */
  fontSize: number;
  verticalAlign?: React.CSSProperties["verticalAlign"];
  emojiStyle?: React.CSSProperties;
}

/**
 * Inline wrapper around renderWithEmoji. Renders a React.Fragment of text +
 * emoji <img> runs. Use where a component currently renders a raw `{text}`
 * child and you have the surrounding font size in px.
 */
export const EmojiText: React.FC<EmojiTextProps> = ({
  children,
  fontSize,
  verticalAlign,
  emojiStyle,
}) => {
  const text = typeof children === "string" ? children : "";
  return <>{renderWithEmoji(text, fontSize, { verticalAlign, emojiStyle })}</>;
};

/**
 * Emoji — render emojis as inline PNG data-URI <img> elements.
 *
 * Why images, not the system emoji font: VanillaSky renders the same scene
 * three ways — real-DOM preview, client SVG-as-image export, server Puppeteer.
 * Raw-unicode emojis fall through to whatever emoji font the OS has (Mac=Apple,
 * Linux=Noto), so preview and export disagree. Inlining each emoji as a
 * data-URI <img> renders the SAME PNG in all three. Critically, the
 * client export rasterizes the frame via <img src="data:image/svg+xml">, which
 * can ONLY load inlined data-URI images (not @font-face, not external URLs) —
 * so data URIs are exactly what works there.
 *
 * Source artwork: emoji-datasource-google (Google Noto emoji set, Apache-2.0).
 * The map ships inside the publicly redistributed skill tarball, and Apple's
 * artwork is not licensed for redistribution — Noto's Apache-2.0 is. The set
 * is swappable via the generator's EMOJI_SET constant
 * (scripts/generate-emoji-map.mjs).
 *
 * Bundle: the generated char→dataURI map is ~1.1MB of base64, so it is
 * LAZY-LOADED via dynamic import and never enters the initial app bundle. The
 * import is kicked off eagerly at module load (below) — long before any export
 * or screenshot — so by the time a frame is captured the map has resolved.
 * Until it resolves, <Emoji> renders the raw unicode char, then re-renders to
 * the image when the map lands. Any emoji not in the map also falls back to the
 * raw char, so nothing ever breaks for custom/unmapped emojis.
 */

import * as React from "react";

let EMOJI_MAP: Record<string, string> | null = null;
let loadPromise: Promise<Record<string, string>> | null = null;
const subscribers = new Set<() => void>();

function loadEmojiMap(): Promise<Record<string, string>> {
  if (loadPromise) return loadPromise;
  loadPromise = import("./emoji-map.generated")
    .then((mod) => {
      EMOJI_MAP = mod.default;
      subscribers.forEach((fn) => fn());
      return EMOJI_MAP;
    })
    .catch((err) => {
      // Network/chunk failure: leave map null → everything falls back to char.
      console.warn("[emoji] failed to load emoji map:", err);
      EMOJI_MAP = {};
      return EMOJI_MAP;
    });
  return loadPromise;
}

// Kick off the load immediately when this module is first imported (app/registry
// init), so the map is ready well before any export or server screenshot.
loadEmojiMap();

/**
 * Resolve once the emoji-PNG map has loaded (or definitively failed). Render
 * paths that capture frames MUST await this before their first capture so they
 * never screenshot a frame while emoji are still raw-unicode chars:
 *   - server: Render.tsx awaits before setting window.__ready
 *   - client export: export-video.ts awaits in the media-preload step
 * The preview path doesn't capture, so it can stay lazy (subscribers re-render
 * char → image when the map lands). On chunk failure this resolves to {} so
 * the await never hangs — everything falls back to the raw char.
 */
export function ensureEmojiMap(): Promise<Record<string, string>> {
  return loadEmojiMap();
}

/**
 * Returns the emoji-PNG data URI for an emoji char, or null if the map hasn't
 * loaded yet or the char isn't in the set (caller should fall back to the char).
 */
export function emojiToDataUri(char: string): string | null {
  if (!EMOJI_MAP) return null;
  const key = (char || "").trim();
  if (EMOJI_MAP[key]) return EMOJI_MAP[key];
  // Tolerate a trailing variation selector mismatch (U+FE0F).
  const stripped = key.replace(/️/g, "");
  if (stripped !== key && EMOJI_MAP[stripped]) return EMOJI_MAP[stripped];
  return null;
}

/** Subscribe to map-loaded so a component re-renders char → image when ready. */
function useEmojiMapReady(): boolean {
  const [, force] = React.useReducer((n: number) => n + 1, 0);
  React.useEffect(() => {
    if (EMOJI_MAP) return;
    const fn = () => force();
    subscribers.add(fn);
    loadEmojiMap();
    return () => {
      subscribers.delete(fn);
    };
  }, []);
  return EMOJI_MAP != null;
}

export interface EmojiProps {
  /** The emoji character(s), e.g. "🎉". */
  char: string;
  /** Box size in px — matches the prior glyph's font-size so layout is identical. */
  size: number;
  /** vertical-align for inline flow. Defaults to a glyph-like baseline nudge. */
  verticalAlign?: React.CSSProperties["verticalAlign"];
  /** Extra styles merged onto the <img> (or fallback <span>). */
  style?: React.CSSProperties;
}

/**
 * Renders an emoji as an inline emoji-PNG <img> when available, else the raw
 * unicode char in a same-size box (so scale/opacity/transform are unchanged).
 */
export const Emoji: React.FC<EmojiProps> = ({ char, size, verticalAlign = "-0.15em", style }) => {
  useEmojiMapReady();
  const uri = emojiToDataUri(char);

  if (!uri) {
    // Fallback: raw char sized to the same box so layout/scale are preserved.
    return (
      <span
        style={{
          fontSize: size,
          lineHeight: 1,
          display: "inline-block",
          ...style,
        }}
      >
        {char}
      </span>
    );
  }

  return (
    <img
      src={uri}
      alt={char}
      width={size}
      height={size}
      style={{
        width: size,
        height: size,
        objectFit: "contain",
        display: "inline-block",
        verticalAlign,
        ...style,
      }}
    />
  );
};

/**
 * normalize-var — Defensive parsing for structured template variables.
 *
 * LLMs may pass variables as colon-separated strings (expected), JSON strings,
 * or raw objects. These helpers normalize any format to the colon-separated
 * string that existing template parsers expect.
 */

/**
 * Normalize a structured variable (e.g. notif1, transaction1) to a colon-separated string.
 *
 * Accepts:
 *  - Colon-separated string: "🔔:App:Hello:1m" → passed through
 *  - JSON string: '{"emoji":"🔔","app":"App"}' → parsed and mapped
 *  - Object: {emoji: "🔔", app: "App"} → mapped to colon-separated
 *
 * @param raw - The variable value (string, object, or unknown)
 * @param keyAliases - Array of alias arrays, one per field position.
 *   e.g. [["emoji"], ["app", "title", "appName"], ["message", "body", "text"], ["time"]]
 */
export function normalizeStructuredVar(
  raw: unknown,
  keyAliases: string[][],
): string {
  if (typeof raw === "string") {
    const trimmed = raw.trim();
    if (trimmed.startsWith("{")) {
      try {
        const obj = JSON.parse(trimmed);
        if (typeof obj === "object" && obj !== null) {
          return extractFromObject(obj, keyAliases);
        }
      } catch {
        // Not valid JSON — pass through as regular string
      }
    }
    return raw;
  }

  if (typeof raw === "object" && raw !== null) {
    return extractFromObject(raw as Record<string, unknown>, keyAliases);
  }

  return String(raw || "");
}

function extractFromObject(
  obj: Record<string, unknown>,
  keyAliases: string[][],
): string {
  return keyAliases
    .map((aliases) => {
      for (const key of aliases) {
        if (obj[key] !== undefined && obj[key] !== null && obj[key] !== "") {
          return String(obj[key]);
        }
      }
      return "";
    })
    .join(":");
}

/**
 * Normalize a simple text variable for chat templates (msg1-msg4).
 *
 * Accepts:
 *  - Plain string: "Hello" → passed through
 *  - String with side: "Hello|in" → passed through
 *  - JSON string: '{"text":"Hello","side":"in"}' → "Hello|in"
 *  - Object: {text: "Hello", side: "in"} → "Hello|in"
 */
export function normalizeTextVar(raw: unknown): string {
  if (typeof raw === "string") {
    const trimmed = raw.trim();
    if (trimmed.startsWith("{")) {
      try {
        const obj = JSON.parse(trimmed);
        if (typeof obj === "object" && obj !== null) {
          return extractTextFromObject(obj);
        }
      } catch {
        // Not valid JSON
      }
    }
    return raw;
  }

  if (typeof raw === "object" && raw !== null) {
    return extractTextFromObject(raw as Record<string, unknown>);
  }

  return String(raw || "");
}

function extractTextFromObject(obj: Record<string, unknown>): string {
  const text = String(
    obj.text || obj.message || obj.body || obj.content || "",
  );
  const side = String(obj.side || obj.direction || "").toLowerCase();
  if (
    side === "in" ||
    side === "left" ||
    side === "incoming" ||
    side === "received"
  ) {
    return text + "|in";
  }
  if (
    side === "out" ||
    side === "right" ||
    side === "outgoing" ||
    side === "sent"
  ) {
    return text + "|out";
  }
  return text;
}

/**
 * Scene template types.
 *
 * A template is a reusable React component that defines how a scene looks.
 * It declares what variables it needs (auto-shown as input fields in the Studio)
 * and receives universal settings as props.
 *
 * Templates are searchable by AI via description, category, jobs, register,
 * and useWhen guidance.
 * The variable schema enables any LLM to fill in template variables via JSON.
 */

import type { ResolvedTokens } from "../theme";
import type { GlobalStyle, VariableField, SafeZone } from "../video-config";

/**
 * Props passed to every scene template component.
 *
 * All animation must be driven by `progress` (0→1). No CSS animations,
 * no Framer Motion, no requestAnimationFrame. Use interpolate/spring
 * from animation-utils.ts.
 *
 * Scale factor: use `Math.min(width, height) / 1080` — normalizes to
 * the short edge so visuals are consistent across portrait and landscape.
 */
export interface SceneTemplateProps {
  variables: Record<string, unknown>;
  style: GlobalStyle;
  /** 0→1 through the scene's duration */
  progress: number;
  /** 0→1 beat pulse intensity */
  beatIntensity: number;
  /** 1080 (portrait) or 1920 (landscape) */
  width: number;
  /** 1920 (portrait) or 1080 (landscape) */
  height: number;
  /** Video-level default text effect (for templates that opt in via usesGlobalTextEffect) */
  textArchetype?: string;
  /** How text leaves the scene (fade / shrink / pop / blur-scale). Falls back to a sensible default per textArchetype when undefined. */
  /** Video-level default background effect (for templates that opt in via usesGlobalBackgroundEffect) */
  backgroundEffect?: string;
  /** Platform-aware safe zone insets in pixels — use for text placement */
  safeZone: SafeZone;
  /** Scene duration in seconds — use for time-based (not progress-based) animations */
  sceneDuration?: number;
  /**
   * Brand tokens already resolved from `style`. Built-in templates import
   * resolveTokens directly; an ejected `custom_*` scene can't import anything,
   * so without this it has no way to reach the same values and ends up
   * hardcoding white, black and shadows — the body then looks generic next to
   * a frame that IS using the brand.
   */
  tokens?: ResolvedTokens;
  /**
   * True when the preview player is actively advancing progress; false when paused.
   * Templates that play HTML5 <video> elements should pause them when this is false.
   * Undefined (export capture path) is treated as true.
   */
  isPlaying?: boolean;
}

/**
 * What a template can DO inside a video. A template can serve more than
 * one job — `bigNumber` is `["claim", "proof"]`; `media` is
 * `["atmosphere", "setup"]`. Used by the chat composer to pick templates
 * by scene-job rather than by the (less useful) category bucket.
 *
 * - `setup` — opens the world, names the subject, frames the question
 * - `claim` — makes a falsifiable statement the rest of the video earns
 * - `proof` — backs a claim with a number, quote, mockup, code, or chart
 * - `atmosphere` — breathing room; ties scenes together visually
 * - `payoff` — punchline, reveal, or satisfying answer to an earlier setup
 * - `punctuation` — short energy beat that breaks pattern or lands a joke
 * - `ask` — pushes the viewer to the next action; closer-territory only
 */
export type TemplateJob = "setup" | "claim" | "proof" | "atmosphere" | "payoff" | "punctuation" | "ask";

/**
 * The visual register a template lives in — what the *viewer* notices
 * before reading any copy. The chat's diversity rule reads this rather
 * than `category` because two `card-led` bodies look the same to the
 * viewer even when they're a `testimonial` and a `bigNumber`.
 *
 * - `motion-led` — animation IS the content (confetti, emoji rain, charts)
 * - `typography-led` — text fills the frame (bigNumber, ctaLogo, tripleStats)
 * - `device-led` — phone/browser/terminal frame is the focal element
 * - `card-led` — quote/feature/comparison cards
 * - `mockup-led` — full UI surface (chat thread, search results, app feed)
 */
export type TemplateRegister =
  | "motion-led"
  | "typography-led"
  | "device-led"
  | "card-led"
  | "mockup-led";

/**
 * A registered scene template.
 */
export interface SceneTemplate {
  id: string;
  /** Built-in templates leave these blank — DB owns them. Vibecoded
   *  templates carry their own here since they have no DB row. */
  label?: string;
  description?: string;
  category?: string | null;
  /** What this template DOES inside a video. 1-3 jobs. See TemplateJob. */
  jobs?: TemplateJob[];
  /** The visual register the template lives in. See TemplateRegister. */
  register?: TemplateRegister;
  /** Semantic selection guidance: when this template is the right choice. */
  useWhen?: string;
  /** Thumbnail URL for visual picker (optional) */
  thumbnail?: string;
  /** If true, template consumes the video-level defaultTextArchetype */
  usesGlobalTextEffect: boolean;
  /** If true, template uses the video-level defaultTransition */
  usesGlobalTransition: boolean;
  /** If true, template uses the video-level defaultBackgroundEffect */
  usesGlobalBackgroundEffect: boolean;
  /**
   * Spatial budget for text effects.
   * - "tight" (default): text shares the frame with UI (mockup, chart). Expressive
   *   effects are auto-clamped to contained equivalents to prevent clipping.
   * - "open": text is the focal element (bg-* templates). All effects allowed.
   */
  textCanvas?: "tight" | "open";
  /**
   * Hard input gates — what this template needs from the user's input to fire
   * legitimately. The AI uses these to filter out templates that would force
   * it to invent content (e.g. \`bigNumber\` without a real number).
   *
   * Set to true when the template's value depends on input that the model
   * can't fabricate honestly: a stat, a quote, an uploaded screenshot.
   * Defaults to false (no constraint).
   */
  requiresStat?: boolean;
  requiresQuote?: boolean;
  requiresScreenshot?: boolean;
  /** Template can be backed by Pexels stock footage (e.g. \`media\`). */
  allowsStockMedia?: boolean;
  /** Variable schema — Studio auto-generates inputs from this */
  variableSchema: Record<string, VariableField>;
  /** Default values for all variables */
  defaultVariables: Record<string, unknown>;
  /** Minimum scene duration in seconds */
  minDuration?: number;
  /** Recommended scene duration in seconds */
  preferredDuration?: number;
  /** The React component that renders this template */
  component: React.FC<SceneTemplateProps>;
}

/**
 * Serializable template metadata (no component) — for edge functions, API, MCP.
 */
export interface SceneTemplateMetadata {
  id: string;
  usesGlobalTextEffect: boolean;
  usesGlobalTransition: boolean;
  usesGlobalBackgroundEffect: boolean;
  textCanvas?: "tight" | "open";
  /** Hard input gates — see SceneTemplate.requiresStat etc. */
  requiresStat?: boolean;
  requiresQuote?: boolean;
  requiresScreenshot?: boolean;
  allowsStockMedia?: boolean;
  /** What this template DOES inside a video. 1-3 jobs. See TemplateJob. */
  jobs?: TemplateJob[];
  /** The visual register the template lives in. See TemplateRegister. */
  register?: TemplateRegister;
  /** Semantic selection guidance: when this template is the right choice. */
  useWhen?: string;
  variableSchema: Record<string, VariableField>;
  defaultVariables: Record<string, unknown>;
  minDuration?: number;
  preferredDuration?: number;
}
